<?php $title="Students";require "../includes/header.php";
$q=trim($_GET['q']??'');$dept=(int)($_GET['department_id']??0);
$sql="SELECT s.*,d.name dept FROM students s LEFT JOIN departments d ON d.id=s.department_id WHERE 1";$p=[];
if($q){$sql.=" AND (s.name LIKE ? OR s.roll LIKE ?)";$p[]="%$q%";$p[]="%$q%";}if($dept){$sql.=" AND s.department_id=?";$p[]=$dept;}
$sql.=" ORDER BY s.id DESC";$st=$pdo->prepare($sql);$st->execute($p);$students=$st->fetchAll();$deps=$pdo->query("SELECT * FROM departments ORDER BY name")->fetchAll();
?><div class="d-flex justify-content-between mb-3"><h2 class="page-title">Students</h2><a href="add.php" class="btn btn-primary">+ Add Student</a></div>
<form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search name or roll"></div><div class="col-md-4"><select name="department_id" class="form-select"><option value="0">All Departments</option><?php foreach($deps as $d):?><option value="<?=$d['id']?>" <?=$dept==$d['id']?'selected':''?>><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-dark w-100">Filter</button></div></form>
<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Roll</th><th>Name</th><th>Department</th><th>Semester</th><th>Phone</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><?=$s['roll']?></td><td><?=htmlspecialchars($s['name'])?></td><td><?=htmlspecialchars($s['dept']??'-')?></td><td><?=$s['semester']?></td><td><?=htmlspecialchars($s['phone'])?></td><td><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?=$s['id']?>">Edit</a> <a data-confirm="Delete this student and attendance records?" class="btn btn-sm btn-outline-danger" href="delete.php?id=<?=$s['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require "../includes/footer.php";?>